import assert from 'node:assert/strict';
import test from 'node:test';
import {readFileSync} from 'node:fs';
import {GP_ACTIVATION_PATHS,GP_ACTIVATION_ORIGINAL_BLOBS,enableGpDirectoryConfiguration,disableGpDirectoryConfiguration,validateGpActivationConfigurations,validateGpActivationInputs,gpActivationSha256,gpActivationGitBlob,gpActivationBindingsSha256} from './gp-directory-activation-contract-20261015.mjs';
const read=p=>readFileSync(new URL(p,import.meta.url),'utf8');
const core=read('gpFlagOriginalCore_0.jsonc'),coreOn=read('gpFlagOriginalCore_1.jsonc'),hqOn=read('gpActivationHqAuthority.jsonc'),hq=disableGpDirectoryConfiguration('wrangler.hq-management.jsonc',hqOn);
const before={'wrangler.jsonc':core,'wrangler.coaching.jsonc':core,'wrangler.hq-management.jsonc':hq};
const after=()=>Object.fromEntries(GP_ACTIVATION_PATHS.map(p=>[p,enableGpDirectoryConfiguration(p,before[p])]));
const base='a'.repeat(40),now=Date.parse('2026-10-15T01:00:00Z');
const run=(id,path)=>({id,path,status:'completed',conclusion:'success',head_sha:base,head_branch:'main',head_repository:{full_name:'shiftsometimber/shift-core'},event:'push',html_url:'https://github.com/shiftsometimber/shift-core/actions/runs/'+id});
const provider=id=>({source:base,run:id,deploymentId:'11111111-1111-1111-1111-111111111111',versionId:'22222222-2222-2222-2222-222222222222',percentage:100,gpEnabled:false,bundleSha256:'b'.repeat(64),otherBindingsSha256:'e'.repeat(64),bundleBytes:100});
function input(){const assets=['member-details.mjs','member-details.css','gp-form.mjs'].map(p=>({url:'https://shiftsometimber.co.uk/assets/member-experience/'+p,sha256:'c'.repeat(64)}));const live={schema:'shift-gp-code-before-directory-activation/v1',capturedAt:'2026-10-15T00:59:00Z',source:base,main:base,core:provider(1),hq:{...provider(2),partnersEnabled:true},staticHq:{repository:'shiftsometimber/shift-hq',source:'d'.repeat(40),tree:'a5a7d21d9a6e92e6a1a49554f718b586be14622a',approvedPrHead:'7a0087c075c674828313ec9b1048165275c244d8',deploymentId:'33333333-3333-3333-3333-333333333333',versionId:'44444444-4444-4444-4444-444444444444',percentage:100,assetsVerified:true,gpModuleSha256:'e'.repeat(64)},directory:{version:'672021e21d318162d9aa550f',complete:1,productionWrites:0},memberCode:{source:base,status:'code_only_verified',flagsOff:true,featureAcceptance:false,realCustomerWrites:0,notificationsSent:0,assetsBefore:assets,assetsAfter:structuredClone(assets)},hqSignedInAcceptance:false};return{acceptedBase:base,coreRun:run(1,'.github/workflows/cloudflare-production-promote.yml'),hqRun:run(2,'.github/workflows/hq-management-release.yml'),live,now};}
function seal(x){x.liveBytes=JSON.stringify(x.live);x.liveSha256=gpActivationSha256(x.liveBytes);return x;}
test('the two original source approvals and inverses are exact actual Git blobs',()=>{for(const[p,value]of[['wrangler.jsonc',coreOn],['wrangler.hq-management.jsonc',hqOn]]){assert.equal(gpActivationGitBlob(before[p]),GP_ACTIVATION_ORIGINAL_BLOBS[p].before);assert.equal(gpActivationGitBlob(value),GP_ACTIVATION_ORIGINAL_BLOBS[p].after);assert.equal(enableGpDirectoryConfiguration(p,before[p]),value);assert.equal(disableGpDirectoryConfiguration(p,value),before[p]);}});
test('only the third physical core mirror is added, all unrelated configuration bytes remain',()=>{const a=after();assert.equal(validateGpActivationConfigurations(before,a),true);assert.equal(a['wrangler.coaching.jsonc'],coreOn);for(const p of GP_ACTIVATION_PATHS)assert.equal(disableGpDirectoryConfiguration(p,a[p]),before[p]);});
test('unrelated config and partner changes are rejected',()=>{for(const p of GP_ACTIVATION_PATHS){const a=after();a[p]+='\n';assert.throws(()=>validateGpActivationConfigurations(before,a));}});
test('unknown paths, duplicate flags, pre-existing false flags and wrong anchors are rejected',()=>{assert.throws(()=>enableGpDirectoryConfiguration('new-worker.jsonc',core));assert.throws(()=>enableGpDirectoryConfiguration('wrangler.jsonc',coreOn));assert.throws(()=>enableGpDirectoryConfiguration('wrangler.jsonc',core+'"MEMBER_GP_DIRECTORY_V2_ENABLED":"false"'));assert.throws(()=>enableGpDirectoryConfiguration('wrangler.jsonc',core.replace('"MEMBER_GP_LOOKUP_ENABLED"','"OTHER_LOOKUP"')));assert.throws(()=>disableGpDirectoryConfiguration('wrangler.jsonc',coreOn+coreOn));});
test('a mirrored config may not drift before or after activation',()=>{const b={...before,'wrangler.coaching.jsonc':core+'\n'};assert.throws(()=>validateGpActivationConfigurations(b,after()));const a=after();a['wrangler.coaching.jsonc']+='\n';assert.throws(()=>validateGpActivationConfigurations(before,a));});
test('strict terminal and fresh serving inputs produce prepared authority without feature acceptance',()=>{const out=validateGpActivationInputs(seal(input()));assert.equal(out.source,base);assert.equal(out.featureAcceptance,false);assert.equal(out.finalHolderAcceptanceStillRequired,true);assert.equal(out.hq.partnersEnabled,true);});
test('the receipt cannot be replaced after its expected hash was selected',()=>{const x=seal(input());x.liveBytes+='\n';assert.throws(()=>validateGpActivationInputs(x),/identity/);});
test('missing, unfinished, wrong-head and wrong-repository terminal runs fail',()=>{for(const[part,key,value]of[['coreRun','status','in_progress'],['hqRun','conclusion','failure'],['coreRun','head_sha','f'.repeat(40)],['hqRun','head_branch','release'],['coreRun','path','.github/workflows/unrelated.yml'],['hqRun','html_url','https://example.test/2'],['coreRun','event','pull_request'],['coreRun','head_repository',{full_name:'other/repo'}]]){const x=input();x[part][key]=value;assert.throws(()=>validateGpActivationInputs(seal(x)));}});
test('same accepted head must be serving both providers with flags off and all traffic',()=>{for(const[part,key,value]of[['core','source','f'.repeat(40)],['hq','run',7],['core','percentage',99],['hq','gpEnabled',true],['hq','partnersEnabled',false],['core','bundleBytes',0],['hq','versionId','unknown']]){const x=input();x.live[part][key]=value;assert.throws(()=>validateGpActivationInputs(seal(x)));}});
test('fresh receipt timestamps reject stale, future and missing captures',()=>{for(const stamp of ['2026-10-15T00:44:59Z','2026-10-15T01:00:01Z',undefined]){const x=input();if(stamp===undefined)delete x.live.capturedAt;else x.live.capturedAt=stamp;assert.throws(()=>validateGpActivationInputs(seal(x)),/Fresh dated/);}});
test('static HQ source, approved tree, packaging and actual directory are mandatory',()=>{for(const[part,key,value]of[['staticHq','tree','f'.repeat(40)],['staticHq','assetsVerified',false],['staticHq','approvedPrHead','f'.repeat(40)],['directory','complete',0],['directory','productionWrites',1],['directory','version','reimported']]){const x=input();x.live[part][key]=value;assert.throws(()=>validateGpActivationInputs(seal(x)));}});
test('code-only source proof cannot claim feature acceptance, notifications or real-customer writes',()=>{for(const[key,value]of[['featureAcceptance',true],['flagsOff',false],['realCustomerWrites',1],['notificationsSent',1],['status','verified']]){const x=input();x.live.memberCode[key]=value;assert.throws(()=>validateGpActivationInputs(seal(x)));}});
test('all three exact served assets must be unchanged in the ordinary existing holder flow',()=>{const x=input();x.live.memberCode.assetsAfter[0].sha256='f'.repeat(64);assert.throws(()=>validateGpActivationInputs(seal(x)));const y=input();y.live.memberCode.assetsBefore[1]={...y.live.memberCode.assetsBefore[0]};y.live.memberCode.assetsAfter=structuredClone(y.live.memberCode.assetsBefore);assert.throws(()=>validateGpActivationInputs(seal(y)));});
test('genuine later HQ acceptance may be recorded but never inferred by this code-only layer',()=>{const x=input();x.live.hqSignedInAcceptance=true;const out=validateGpActivationInputs(seal(x));assert.equal(out.featureAcceptance,false);assert.equal(out.finalHolderAcceptanceStillRequired,true);});
test('other binding digests preserve every value and ignore only the one approved V2 flag',()=>{const a=[{name:'A',type:'plain_text',text:'true'},{name:'B',type:'secret_text'}],flag={name:'MEMBER_GP_DIRECTORY_V2_ENABLED',type:'plain_text',text:'true'},hash=gpActivationBindingsSha256(a);assert.equal(gpActivationBindingsSha256([...a].reverse().map(b=>Object.fromEntries(Object.entries(b).reverse()))),hash);assert.equal(gpActivationBindingsSha256([...a,flag]),hash);assert.notEqual(gpActivationBindingsSha256([{...a[0],text:'false'},a[1]]),hash);assert.throws(()=>gpActivationBindingsSha256([...a,{...a[0]}]),/Duplicate provider binding/);});
